global class LongTextBoundaryObserver {
 public static Map<String,Object> text(String value) {
  List<Integer> units=new List<Integer>();
  if(value!=null) for(Integer i=0;i<value.length();i++) units.add(value.charAt(i));
  return new Map<String,Object>{'value'=>value,'length'=>value==null?null:value.length(),'utf16CodeUnits'=>units};
 }
 global static List<Object> observe(String operation) {
  List<String> values=new List<String>{'a\n','a\nb','\na','a\r\n','a\n\n','a'};
  List<Object> observations=new List<Object>();
  for(Integer i=0;i<values.size();i++) {
   String source=values[i];
   BoundaryTextNote__c record=new BoundaryTextNote__c(Name='Boundary '+i,StableKey__c=operation+'-'+i,Transcript__c='seed');
   Map<String,Object> observation=new Map<String,Object>{'shape'=>i,'operation'=>operation,'source'=>text(source),'rawExceptionMessage'=>text(new IllegalArgumentException(source).getMessage()),'declaredLength'=>BoundaryTextNote__c.Transcript__c.getDescribe().getLength()};
   if(operation=='update'||operation=='upsertUpdate') insert record;
   if(operation=='upsertUpdate') record=new BoundaryTextNote__c(Name='Boundary '+i,StableKey__c=operation+'-'+i);
   record.Transcript__c=source;
   observation.put('callerBefore',text(record.Transcript__c));
   try {
    if(operation=='insert') insert record;
    else if(operation=='update') update record;
    else if(operation=='upsertUpdate'||operation=='upsertInsert') upsert record StableKey__c;
    else {System.assert(false,'Unknown operation');}
    observation.put('callerAfter',text(record.Transcript__c));
    Id recordId=record.Id;
    BoundaryTextNote__c queried=[SELECT Transcript__c FROM BoundaryTextNote__c WHERE Id=:recordId];
    observation.put('queried',text(queried.Transcript__c));
    SObject dynamicRow=Database.query('SELECT Transcript__c FROM BoundaryTextNote__c WHERE Id=:recordId');
    observation.put('dynamicQueried',text((String)dynamicRow.get('Transcript__c')));
    observation.put('readBackComplete',true);
   } catch(Exception failure) {
    observation.put('readBackComplete',false);
    observation.put('failureType',failure.getTypeName());
    observation.put('failureMessage',text(failure.getMessage()));
   }
   observations.add(observation);
  }
  return observations;
 }
 global static void emit(String row,String operation) {
  List<Object> observation=observe(operation);
  String payload=JSON.serialize(new Map<String,Object>{'row'=>row,'operation'=>operation,'observations'=>observation});
  Blob bytes=Blob.valueOf(payload);
  String encoded=EncodingUtil.base64Encode(bytes);
  String digest=EncodingUtil.convertToHex(Crypto.generateDigest('SHA-256',bytes));
  String token=EncodingUtil.convertToHex(Crypto.generateAesKey(128));
  Integer count=(encoded.length()+399)/400;
  for(Integer i=0;i<count;i++) {
   Integer first=i*400;
   Integer last=Math.min(first+400,encoded.length());
   System.debug(LoggingLevel.ERROR,'TEXT_CHUNK|'+row+'|'+token+'|'+i+'|'+count+'|'+encoded.substring(first,last));
  }
  System.assert(false,'TEXT_RESULT|'+row+'|'+token+'|sha256='+digest+'|chunks='+count+'|encodedChars='+encoded.length());
 }
}

